class.BCsectionTwo-top-chapter
<js>
if (src.match(/data\-x/)) {
  result.sort((a, b) => a.attr("data-x") - b.attr("data-x"));
  result.select("a");
} else {
  result = result.select("a")
  try {
    eval(src.match(/var originalOrder = \[.*\];/)[0])
    list = []
    for (i in result) {
      list[originalOrder[i]] = result[i]
    }
    list
  } catch (err) {
    result;
  }
}
</js>

ruleToc.chapterName:
html<js>
r=result
try{
	rr=r.match(/= ?"([^"]+)"/g)
	for(i in rr){
	//	java.log(rr[i])
	 a=rr[i].match(/"(.*)"/)[1]
	 if(/L2Jv|\/book|javas|^g$/.test(a)){}else{text=a}
		}
text
}catch{
	java.getString("text")
}
</js>

ruleToc.chapterUrl:
html<js>
r=result
try{
	rr=r.match(/= ?"([^"]+)"/g);
	for(i in rr){
	 a=rr[i].match(/"(.*)"/)[1]
	 if(/L2Jv/.test(a)){
	 		 	href=java.base64Decode(a)
	 	}else if(/html/.test(a)){href=a}
	}
if(href==""){
		href=java.getString("a@href")
		}
href
}catch{
	java.getString("href")
}
</js>

